import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  image?: string;
  sources?: GroundingSource[];
  timestamp: Date;
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface Location {
  latitude: number;
  longitude: number;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GroundingSource, Location } from "../types";

const SYSTEM_INSTRUCTION = `
आप "किसान-चक्षु AI" (Kisan-Chaksun AI) हैं, जो भारतीय किसानों के लिए एक उन्नत कृषि विशेषज्ञ और सलाहकार है। 
आपका लक्ष्य किसानों को वैज्ञानिक, सटीक और आसान भाषा में सलाह देना है।

नियम:
1. भाषा: प्राथमिक उत्तर सरल हिंदी (Devanagari) में दें। यदि उपयोगकर्ता किसी अन्य भारतीय भाषा में पूछता है, तो उसी में उत्तर दें।
2. इमेज एनालिसिस: यदि उपयोगकर्ता फसल या पत्ती की फोटो अपलोड करता है, तो उसे पहचानें, बीमारी/कीट का निदान करें और समाधान दें।
3. उत्तर की संरचना (Strict Structure):
   - पहचान (Identification): फसल और विशिष्ट समस्या/बीमारी का नाम।
   - समाधान (The Cure): 
     - जैविक विधि (Organic Method): देसी और प्राकृतिक तरीके।
     - रासायनिक विधि (Chemical Method): अनुशंसित कीटनाशक/उर्वरक और उनकी सटीक मात्रा (Dosage)।
   - रोकथाम (Prevention): भविष्य में इस समस्या से बचने के सुझाव।
   - मंडी टिप (Market Tip): फसल को कब और कहाँ बेचने पर अधिकतम लाभ होगा, इसकी भविष्यवादी सलाह।
4. गूगल सर्च ग्राउंडिंग: मंडी के ताज़ा भाव और मौसम की जानकारी के लिए हमेशा गूगल सर्च टूल का उपयोग करें।
5. सुरक्षा (Safety): हमेशा यह डिस्क्लेमर शामिल करें कि "रसायनों का उपयोग स्थानीय सरकारी दिशा-निर्देशों के अनुसार ही करें।"
6. लहजा: सहानुभूतिपूर्ण, पेशेवर और उत्साहजनक।

यदि फोटो खेती से संबंधित नहीं है, तो विनम्रतापूर्वक कहें कि आप केवल कृषि संबंधी प्रश्नों में मदद कर सकते हैं।
`;

export const analyzeCrop = async (
  prompt: string,
  image?: string,
  location?: Location
): Promise<{ text: string; sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const contents: any[] = [];

  if (image) {
    contents.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: image.split(',')[1],
      },
    });
  }

  contents.push({ text: prompt });

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: contents },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      tools: [{ googleSearch: {} }],
    },
  });

  const text = response.text || "क्षमा करें, मैं अभी आपकी सहायता करने में असमर्थ हूँ। कृपया पुनः प्रयास करें।";

  const sources: GroundingSource[] = [];
  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks) {
    groundingChunks.forEach((chunk: any) => {
      if (chunk.web) {
        sources.push({
          title: chunk.web.title,
          uri: chunk.web.uri,
        });
      }
    });
  }

  return { text, sources };
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  AlertCircle, 
  Loader2,
  Image as ImageIcon,
  X,
  ExternalLink,
  MessageSquare
} from 'lucide-react';
import { analyzeCrop } from './services/geminiService';
import { Message, GroundingSource, Location } from './types';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [location, setLocation] = useState<Location | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Geolocation disabled", err)
      );
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if (!inputText.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    const currentInput = inputText;
    const currentImage = selectedImage;

    setInputText('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const prompt = currentInput || "कृपया इस फोटो का विश्लेषण करें और कृषि सलाह दें।";
      const { text, sources } = await analyzeCrop(prompt, currentImage || undefined, location || undefined);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources,
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "क्षमा करें, मुझे जानकारी प्राप्त करने में समस्या हो रही है। कृपया अपना इंटरनेट कनेक्शन जांचें और फिर से प्रयास करें।",
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const renderContent = (content: string) => {
    // Basic Markdown-ish parsing for better readability
    return content.split('\n').map((line, i) => {
      if (line.startsWith('- ') || line.startsWith('* ')) {
        return <li key={i} className="ml-4 list-disc">{line.substring(2)}</li>;
      }
      if (line.includes(':')) {
        const [label, ...rest] = line.split(':');
        return <p key={i} className="mb-2"><span className="font-bold text-green-800">{label}:</span>{rest.join(':')}</p>;
      }
      return <p key={i} className="mb-2">{line}</p>;
    });
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto bg-white shadow-2xl">
      {/* Header */}
      <header className="bg-green-600 text-white p-4 shadow-md flex items-center justify-between sticky top-0 z-10">
        <div className="flex items-center gap-3">
          <div className="bg-white p-2 rounded-full">
            <Leaf className="text-green-600 w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold">किसान-चक्षु AI</h1>
            <p className="text-xs text-green-100 flex items-center gap-1">
              <MapPin className="w-3 h-3" /> {location ? "लोकेशन सक्रिय" : "लोकेशन खोज रहा है..."}
            </p>
          </div>
        </div>
        <div className="text-xs bg-green-700 px-3 py-1 rounded-full border border-green-500">
          कृषि विशेषज्ञ 24/7
        </div>
      </header>

      {/* Chat Area */}
      <main 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-4 bg-green-50/30"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-6">
            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center">
              <Leaf className="w-12 h-12 text-green-600 animate-pulse" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-green-800">राम-राम किसान भाइयों!</h2>
              <p className="text-gray-600 mt-2 max-w-md">
                मैं आपका अपना <b>किसान-चक्षु AI</b> सलाहकार हूँ। अपनी फसल की बीमारी का पता लगाने के लिए फोटो भेजें या मंडी भाव पूछें।
              </p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-lg">
              <button 
                onClick={() => setInputText("आज के मंडी भाव क्या हैं?")}
                className="p-3 bg-white border border-green-200 rounded-xl text-green-700 hover:bg-green-100 transition text-sm text-left shadow-sm flex items-center gap-2"
              >
                <Search className="w-4 h-4" /> आज के मंडी भाव?
              </button>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3 bg-white border border-green-200 rounded-xl text-green-700 hover:bg-green-100 transition text-sm text-left shadow-sm flex items-center gap-2"
              >
                <Camera className="w-4 h-4" /> बीमारी की फोटो भेजें
              </button>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div 
              className={`max-w-[85%] rounded-2xl p-4 shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-green-600 text-white rounded-tr-none' 
                  : 'bg-white border border-green-100 text-gray-800 rounded-tl-none'
              }`}
            >
              {msg.image && (
                <div className="mb-3">
                  <img src={msg.image} alt="Crop" className="rounded-lg max-h-60 w-full object-cover border-2 border-green-400/30" />
                </div>
              )}
              <div className="text-sm leading-relaxed whitespace-pre-wrap">
                {msg.role === 'assistant' ? renderContent(msg.content) : msg.content}
              </div>

              {msg.sources && msg.sources.length > 0 && (
                <div className="mt-4 pt-3 border-t border-green-100">
                  <p className="text-xs font-bold text-green-700 mb-2 flex items-center gap-1">
                    <Search className="w-3 h-3" /> ताज़ा जानकारी के स्रोत:
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {msg.sources.map((source, idx) => (
                      <a 
                        key={idx}
                        href={source.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[10px] bg-green-50 text-green-800 px-2 py-1 rounded border border-green-200 hover:bg-green-100 flex items-center gap-1"
                      >
                        {source.title.length > 20 ? source.title.substring(0, 20) + '...' : source.title}
                        <ExternalLink className="w-2 h-2" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              <div className={`text-[10px] mt-2 ${msg.role === 'user' ? 'text-green-200' : 'text-gray-400'}`}>
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-green-100 rounded-2xl p-4 shadow-sm rounded-tl-none flex items-center gap-3">
              <Loader2 className="w-5 h-5 text-green-600 animate-spin" />
              <span className="text-sm text-gray-500 font-medium">विशेषज्ञ सलाह तैयार की जा रही है...</span>
            </div>
          </div>
        )}
      </main>

      {/* Input Section */}
      <footer className="p-4 bg-white border-t border-gray-100 sticky bottom-0">
        {selectedImage && (
          <div className="mb-3 relative inline-block">
            <img 
              src={selectedImage} 
              alt="Preview" 
              className="w-20 h-20 object-cover rounded-lg border-2 border-green-500" 
            />
            <button 
              onClick={() => setSelectedImage(null)}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-lg hover:bg-red-600 transition"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}

        <div className="flex items-end gap-2">
          <div className="flex-1 bg-green-50 rounded-2xl border border-green-200 flex items-center px-4 transition-all focus-within:ring-2 focus-within:ring-green-500 focus-within:bg-white">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="यहाँ पूछें (उदा. आलू की फसल में पीलापन क्यों है?)..."
              className="flex-1 bg-transparent border-none focus:outline-none py-3 text-sm resize-none max-h-32 min-h-[44px]"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
            />
            <div className="flex items-center gap-1 self-end mb-1">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImageSelect} 
                accept="image/*" 
                className="hidden" 
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-2 text-green-600 hover:bg-green-100 rounded-full transition"
                title="फोटो चुनें"
              >
                <Camera className="w-5 h-5" />
              </button>
            </div>
          </div>
          <button
            onClick={handleSend}
            disabled={(!inputText.trim() && !selectedImage) || isLoading}
            className={`p-4 rounded-2xl shadow-lg transition-all transform active:scale-95 ${
              (!inputText.trim() && !selectedImage) || isLoading
                ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                : 'bg-green-600 text-white hover:bg-green-700'
            }`}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Send className="w-6 h-6" />}
          </button>
        </div>

        <p className="text-[10px] text-center text-gray-400 mt-2 flex items-center justify-center gap-1">
          <AlertCircle className="w-3 h-3" /> रसायनों का उपयोग स्थानीय सरकारी दिशा-निर्देशों के अनुसार करें।
        </p>
      </footer>
    </div>
  );
};

export default App;

