export const analyzeCrop = async (
  prompt: string,
  image?: string,
  location?: Location,
  language: string = 'Hindi'
): Promise<{ text: string; sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const contents: any[] = [];

  if (image) {
    contents.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: image.split(',')[1],
      },
    });
  }

  const fullPrompt = `User Location: ${location ? `${location.latitude}, ${location.longitude}` : 'Unknown'}. 
  Selected Language: ${language}.
  User Query: ${prompt}`;

  contents.push({ text: fullPrompt });

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: contents },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      tools: [{ googleSearch: {} }],
    },
  });

  const text = response.text || "क्षमस्व, मी सध्या तुम्हाला मदत करू शकत नाही. कृपया पुन्हा प्रयत्न करा.";

  const sources: GroundingSource[] = [];
  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks) {
    groundingChunks.forEach((chunk: any) => {
      if (chunk.web) {
        sources.push({
          title: chunk.web.title,
          uri: chunk.web.uri,
        });
      }
    });
  }

  return { text, sources };
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  AlertCircle, 
  Loader2,
  X,
  ExternalLink,
  Mic,
  MicOff,
  CloudSun,
  TrendingUp,
  Globe,
  RefreshCw
} from 'lucide-react';
import { analyzeCrop } from './services/geminiService';
import { Message, GroundingSource, Location } from './types';

const LANGUAGES = [
  { code: 'hi', name: 'Hindi', label: 'हिंदी' },
  { code: 'mr', name: 'Marathi', label: 'मराठी' },
  { code: 'pa', name: 'Punjabi', label: 'ਪੰਜਾਬੀ' },
  { code: 'en', name: 'English', label: 'English' }
];

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [location, setLocation] = useState<Location | null>(null);
  const [selectedLang, setSelectedLang] = useState(LANGUAGES[0]);
  const [weatherData, setWeatherData] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    // Initialize Speech Recognition
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputText(prev => prev + ' ' + transcript);
        setIsRecording(false);
      };

      recognitionRef.current.onerror = () => setIsRecording(false);
      recognitionRef.current.onend = () => setIsRecording(false);
    }

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setLocation(loc);
          fetchQuickWeather(loc);
        },
        (err) => console.warn("Geolocation disabled", err)
      );
    }
  }, []);

  const fetchQuickWeather = async (loc: Location) => {
    try {
      // Use Gemini to get a quick summary via search as we don't have a direct weather API key
      const res = await analyzeCrop(`Current weather summary for lat: ${loc.latitude}, lon: ${loc.longitude}`, undefined, loc, selectedLang.name);
      setWeatherData(res.text.split('\n')[0]);
    } catch (e) {
      setWeatherData("मौसम की जानकारी अनुपलब्ध");
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      if (recognitionRef.current) {
        recognitionRef.current.lang = selectedLang.code === 'hi' ? 'hi-IN' : 
                                      selectedLang.code === 'mr' ? 'mr-IN' : 
                                      selectedLang.code === 'pa' ? 'pa-IN' : 'en-IN';
        recognitionRef.current.start();
        setIsRecording(true);
      } else {
        alert("आपका ब्राउज़र वॉइस इनपुट का समर्थन नहीं करता है।");
      }
    }
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async (customPrompt?: string) => {
    const textToSend = customPrompt || inputText;
    if (!textToSend.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      image: selectedImage || undefined,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    const currentImage = selectedImage;

    setInputText('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const { text, sources } = await analyzeCrop(textToSend || "फोटो विश्लेषण", currentImage || undefined, location || undefined, selectedLang.name);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources,
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: "नेटवर्क की समस्या। कृपया पुनः प्रयास करें।",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const renderContent = (content: string) => {
    return content.split('\n').map((line, i) => {
      const trimmed = line.trim();
      if (!trimmed) return <div key={i} className="h-2" />;

      // Highlight sections with emojis or bold headers
      if (trimmed.match(/^[🌿💊🌱🧪🛡️📈]/)) {
        return <h3 key={i} className="font-bold text-green-900 mt-3 mb-1 text-base border-b border-green-100 pb-1">{trimmed}</h3>;
      }

      if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
        return <li key={i} className="ml-4 list-disc text-sm text-gray-700 mb-1">{trimmed.substring(1).trim()}</li>;
      }

      return <p key={i} className="mb-1 text-sm text-gray-700 leading-relaxed">{trimmed}</p>;
    });
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto bg-gray-50 overflow-hidden shadow-2xl border-x border-gray-200">
      {/* Header */}
      <header className="bg-white border-b border-green-100 p-4 sticky top-0 z-20">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-3">
            <div className="bg-green-600 p-2 rounded-xl shadow-inner">
              <Leaf className="text-white w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-black text-green-800 tracking-tight">किसान-चक्षु AI</h1>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="flex h-2 w-2 rounded-full bg-green-500 animate-pulse"></span>
                <p className="text-[10px] font-bold text-green-600 uppercase tracking-widest">Agricultural Expert</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="relative group">
              <button className="flex items-center gap-1 bg-green-50 text-green-700 px-3 py-1.5 rounded-lg border border-green-200 text-xs font-bold hover:bg-green-100">
                <Globe className="w-3.5 h-3.5" />
                {selectedLang.label}
              </button>
              <div className="absolute right-0 mt-2 w-32 bg-white border border-gray-200 rounded-xl shadow-xl hidden group-hover:block z-50 overflow-hidden">
                {LANGUAGES.map(lang => (
                  <button 
                    key={lang.code}
                    onClick={() => setSelectedLang(lang)}
                    className={`w-full text-left px-4 py-2 text-xs hover:bg-green-50 transition ${selectedLang.code === lang.code ? 'bg-green-100 font-bold text-green-800' : 'text-gray-600'}`}
                  >
                    {lang.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Quick Stats Bar */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 no-scrollbar">
          {location && (
            <div className="flex-shrink-0 flex items-center gap-2 bg-blue-50 text-blue-700 px-3 py-1.5 rounded-full border border-blue-100 text-[10px] font-bold">
              <CloudSun className="w-3 h-3" />
              <span className="truncate max-w-[120px]">{weatherData || "मौसम खोज रहा है..."}</span>
            </div>
          )}
          <button 
            onClick={() => handleSend("मेरे क्षेत्र के लिए आज के ताज़ा मंडी भाव क्या हैं?")}
            className="flex-shrink-0 flex items-center gap-2 bg-amber-50 text-amber-700 px-3 py-1.5 rounded-full border border-amber-100 text-[10px] font-bold hover:bg-amber-100"
          >
            <TrendingUp className="w-3 h-3" /> मंडी भाव
          </button>
          <button 
            onClick={() => handleSend("आज के मौसम के अनुसार खेती के लिए क्या सावधानी बरतें?")}
            className="flex-shrink-0 flex items-center gap-2 bg-green-50 text-green-700 px-3 py-1.5 rounded-full border border-green-100 text-[10px] font-bold hover:bg-green-100"
          >
            <RefreshCw className="w-3 h-3" /> मौसम सलाह
          </button>
        </div>
      </header>

      {/* Chat Area */}
      <main 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-center px-4">
            <div className="relative mb-8">
              <div className="absolute inset-0 bg-green-200 rounded-full blur-3xl opacity-30 animate-pulse"></div>
              <div className="relative bg-white p-6 rounded-full shadow-xl border-4 border-green-50">
                <Leaf className="w-16 h-16 text-green-600" />
              </div>
            </div>
            <h2 className="text-2xl font-black text-green-900 mb-2">नमस्ते किसान भाई!</h2>
            <p className="text-gray-500 mb-8 max-w-sm">
              मैं आपकी फसल की सुरक्षा और लाभ बढ़ाने में मदद कर सकता हूँ। फोटो भेजें या बोलकर पूछें।
            </p>
            <div className="grid grid-cols-2 gap-3 w-full max-w-sm">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="flex flex-col items-center gap-2 p-4 bg-white rounded-2xl border-2 border-green-100 hover:border-green-500 hover:shadow-lg transition-all"
              >
                <div className="p-2 bg-green-50 rounded-lg text-green-600"><Camera className="w-6 h-6" /></div>
                <span className="text-xs font-bold text-gray-700">बीमारी पहचानें</span>
              </button>
              <button 
                onClick={toggleRecording}
                className="flex flex-col items-center gap-2 p-4 bg-white rounded-2xl border-2 border-green-100 hover:border-green-500 hover:shadow-lg transition-all"
              >
                <div className="p-2 bg-blue-50 rounded-lg text-blue-600"><Mic className="w-6 h-6" /></div>
                <span className="text-xs font-bold text-gray-700">बोलकर पूछें</span>
              </button>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[90%] md:max-w-[80%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`p-4 rounded-2xl shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-green-700 text-white rounded-tr-none' 
                  : 'bg-white border border-green-50 text-gray-800 rounded-tl-none shadow-md'
              }`}>
                {msg.image && (
                  <div className="mb-3 overflow-hidden rounded-xl border-2 border-green-100/30">
                    <img src={msg.image} alt="Crop" className="w-full object-cover" />
                  </div>
                )}
                <div className="text-sm">
                  {msg.role === 'assistant' ? renderContent(msg.content) : msg.content}
                </div>

                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-3 border-t border-green-50 flex flex-wrap gap-2">
                    {msg.sources.map((source, idx) => (
                      <a 
                        key={idx}
                        href={source.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[10px] font-bold bg-green-50 text-green-700 px-2.5 py-1 rounded-full border border-green-200 hover:bg-green-100 flex items-center gap-1.5"
                      >
                        <Search className="w-2.5 h-2.5" />
                        {source.title.length > 15 ? source.title.substring(0, 15) + '...' : source.title}
                      </a>
                    ))}
                  </div>
                )}
              </div>
              <div className="text-[10px] mt-1.5 px-1 font-bold text-gray-400">
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-green-50 rounded-2xl p-4 shadow-md rounded-tl-none flex items-center gap-3">
              <div className="relative">
                <Loader2 className="w-5 h-5 text-green-600 animate-spin" />
                <div className="absolute inset-0 bg-green-500/20 blur-md animate-pulse"></div>
              </div>
              <span className="text-xs font-bold text-green-800">विशेषज्ञ सलाह तैयार हो रही है...</span>
            </div>
          </div>
        )}
      </main>

      {/* Input Section */}
      <footer className="bg-white border-t border-gray-100 p-4 pb-6">
        {selectedImage && (
          <div className="mb-4 flex items-center gap-2 p-2 bg-green-50 rounded-xl border border-green-200">
            <img src={selectedImage} alt="Preview" className="w-16 h-16 object-cover rounded-lg border-2 border-white shadow-sm" />
            <div className="flex-1">
              <p className="text-[10px] font-black text-green-800 uppercase">फोटो चुनी गई</p>
              <p className="text-[10px] text-green-600">विश्लेषण के लिए भेजें पर क्लिक करें</p>
            </div>
            <button onClick={() => setSelectedImage(null)} className="p-2 bg-white text-red-500 rounded-full shadow-sm hover:text-red-700">
              <X className="w-4 h-4" />
            </button>
          </div>
        )}

        <div className="flex items-center gap-2">
          <div className="flex-1 flex items-center gap-2 bg-gray-100 rounded-2xl p-2 pl-4 border-2 border-transparent focus-within:border-green-500 focus-within:bg-white transition-all shadow-inner">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder={`${selectedLang.label} में पूछें...`}
              className="flex-1 bg-transparent border-none focus:outline-none py-2 text-sm max-h-32 min-h-[40px] resize-none"
              rows={1}
            />
            <div className="flex items-center gap-1">
              <input type="file" ref={fileInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" capture="environment" />
              <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-500 hover:text-green-600 transition">
                <Camera className="w-5 h-5" />
              </button>
              <button 
                onClick={toggleRecording} 
                className={`p-2 rounded-full transition ${isRecording ? 'bg-red-100 text-red-600 animate-pulse' : 'text-gray-500 hover:text-blue-600'}`}
              >
                {isRecording ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
              </button>
            </div>
          </div>

          <button
            onClick={() => handleSend()}
            disabled={(!inputText.trim() && !selectedImage) || isLoading}
            className={`p-4 rounded-2xl shadow-lg transition-all transform active:scale-95 ${
              (!inputText.trim() && !selectedImage) || isLoading
                ? 'bg-gray-200 text-gray-400'
                : 'bg-green-600 text-white hover:bg-green-700 shadow-green-200'
            }`}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Send className="w-6 h-6" />}
          </button>
        </div>

        <div className="flex items-center justify-center gap-2 mt-4 text-[10px] font-bold text-gray-400 uppercase tracking-tighter">
          <AlertCircle className="w-3 h-3 text-amber-500" />
          <span>स्थानीय सरकारी दिशा-निर्देशों का पालन करें</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  AlertCircle, 
  Loader2,
  X,
  Mic,
  Volume2,
  ChevronRight,
  TrendingUp,
  BookOpen,
  MessageSquare,
  ChevronDown,
  CloudSun
} from 'lucide-react';
import { analyzeCrop } from './services/geminiService';
import { Message, Location } from './types';

const LANGUAGES = [
  { code: 'hi', label: 'हिन्दी' },
  { code: 'mr', label: 'मराठी' },
  { code: 'pa', label: 'ਪੰਜਾਬੀ' },
  { code: 'en', label: 'English' }
];

type Tab = 'chat' | 'mandi' | 'technique';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('chat');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: "नमस्ते किसान भाई! मैं किसान-चक्षु AI हूँ। अपनी फसल की फोटो भेजें या बोलकर सवाल पूछें।",
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [city, setCity] = useState("वाराणसी");
  const [selectedLang, setSelectedLang] = useState(LANGUAGES[0]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.onresult = (e: any) => {
        setInputText(e.results[0][0].transcript);
        setIsRecording(false);
      };
      recognitionRef.current.onend = () => setIsRecording(false);
    }
  }, []);

  const speakText = (text: string) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = selectedLang.code === 'hi' ? 'hi-IN' : 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleSend = async () => {
    if (!inputText.trim() && !selectedImage) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    const query = inputText;
    const img = selectedImage;
    setInputText('');
    setSelectedImage(null);

    try {
      const { text, sources } = await analyzeCrop(query, img || undefined, undefined, selectedLang.label);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources,
        timestamp: new Date()
      }]);
    } catch (err) {
      setMessages(prev => [...prev, {
        id: 'err',
        role: 'assistant',
        content: "क्षमा करें, तकनीकी समस्या आई।",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      recognitionRef.current?.start();
      setIsRecording(true);
    }
  };

  return (
    <div className="flex flex-col h-screen max-w-md mx-auto bg-gray-50 font-['Hind'] shadow-2xl relative overflow-hidden">

      {/* Header - Matching Image */}
      <header className="bg-[#14532d] text-white pt-6 pb-4 px-4 shadow-lg z-30">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Leaf className="w-6 h-6 text-green-300" />
            <h1 className="text-xl font-bold tracking-tight">किसान-चक्षु AI</h1>
          </div>
          <div className="flex items-center bg-[#1a4a2e] rounded-md px-2 py-1 border border-green-800 text-xs">
            <span>{selectedLang.label}</span>
            <ChevronDown className="w-3 h-3 ml-1" />
          </div>
        </div>

        {/* City Location Bar - Matching Image */}
        <div 
          onClick={() => {
            const newCity = prompt("अपना शहर दर्ज करें:", city);
            if(newCity) setCity(newCity);
          }}
          className="bg-[#0f3d23] rounded-lg p-3 flex items-center justify-between cursor-pointer border border-green-800/30"
        >
          <div className="flex items-center gap-2">
            <MapPin className="w-4 h-4 text-green-400" />
            <span className="text-sm font-medium">{city} का अपडेट</span>
          </div>
          <ChevronRight className="w-4 h-4 text-green-600" />
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-4 bg-white relative">
        {activeTab === 'chat' && (
          <div className="space-y-6" ref={scrollRef}>
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start animate-fade-in'}`}>
                <div className={`max-w-[85%] relative ${msg.role === 'user' ? 'bg-green-600 text-white rounded-2xl rounded-tr-none' : 'bg-white border border-gray-100 shadow-sm rounded-2xl rounded-tl-none'} p-4`}>
                  {msg.image && <img src={msg.image} className="rounded-lg mb-2 max-h-48 w-full object-cover" />}
                  <p className="text-[15px] leading-relaxed whitespace-pre-wrap">{msg.content}</p>

                  {msg.role === 'assistant' && (
                    <button 
                      onClick={() => speakText(msg.content)}
                      className="mt-3 flex items-center gap-1.5 text-green-600 text-sm font-bold bg-green-50 px-3 py-1.5 rounded-full hover:bg-green-100 transition"
                    >
                      <Volume2 className="w-4 h-4" /> सुनें
                    </button>
                  )}
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex justify-start items-center gap-2 text-green-600 font-medium text-sm animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                खोज रहा हूँ...
              </div>
            )}
          </div>
        )}

        {activeTab === 'mandi' && (
          <div className="space-y-4 pt-2">
            <h2 className="text-lg font-bold text-green-900 border-b pb-2">ताज़ा मंडी भाव और मौसम</h2>
            <div className="grid grid-cols-2 gap-3">
              <div className="bg-amber-50 p-4 rounded-xl border border-amber-100">
                <p className="text-xs text-amber-600 font-bold uppercase">गेहूं (Wheat)</p>
                <p className="text-xl font-bold">₹2,450</p>
                <span className="text-[10px] text-green-600">↑ 2% आज</span>
              </div>
              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                <p className="text-xs text-blue-600 font-bold uppercase">मौसम (Weather)</p>
                <p className="text-xl font-bold">32°C</p>
                <span className="text-[10px] text-blue-500 flex items-center gap-1"><CloudSun className="w-2 h-2" /> साफ़ आसमान</span>
              </div>
            </div>
