import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GroundingSource, Location } from "../types";

const SYSTEM_INSTRUCTION = `
आप "किसान-चक्षु AI" (Kisan-Chaksun AI) हैं, जो भारतीय किसानों के लिए एक उन्नत कृषि विशेषज्ञ और सलाहकार है। 

नियम:
1. भाषा: उपयोगकर्ता की चुनी हुई भाषा में उत्तर दें। 
2. इमेज एनालिसिस: फोटो में फसल की बीमारी पहचानें और जैविक/रासायनिक समाधान दें।
3. उत्तर की संरचना:
   - 🌿 पहचान: बीमारी का सटीक नाम।
   - 💊 समाधान: जैविक (Organic) और रासायनिक (Chemical) दोनों तरीके।
   - 🛡️ रोकथाम: भविष्य के बचाव के तरीके।
   - 📈 मंडी टिप: वर्तमान बाजार रुझान।
4. गूगल सर्च: मंडी भाव और मौसम के लिए हमेशा ताज़ा डेटा खोजें।
5. सुरक्षा: रसायनों के उपयोग के लिए सरकारी नियमों का पालन करने की चेतावनी दें।
`;

export const analyzeCrop = async (
  prompt: string,
  image?: string,
  location?: string,
  language: string = 'Hindi'
): Promise<{ text: string; sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const contents: any[] = [];

  if (image) {
    contents.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: image.split(',')[1],
      },
    });
  }

  const fullPrompt = `City Context: ${location || 'Unknown'}. 
  User Language: ${language}.
  Query: ${prompt}`;

  contents.push({ text: fullPrompt });

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: contents },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      tools: [{ googleSearch: {} }],
    },
  });

  const text = response.text || "क्षमस्व, मी सध्या तुम्हाला मदत करू शकत नाही.";

  const sources: GroundingSource[] = [];
  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks) {
    groundingChunks.forEach((chunk: any) => {
      if (chunk.web) {
        sources.push({
          title: chunk.web.title,
          uri: chunk.web.uri,
        });
      }
    });
  }

  return { text, sources };
};

