            <button onClick={() => setSelectedImage(null)} className="absolute -top-3 -right-3 bg-red-600 text-white rounded-full p-1.5 shadow-lg border-2 border-white">
              <X className="w-3 h-3" />
            </button>
          </div>
        )}
        <div className="flex items-center gap-2 bg-gray-100 rounded-2xl px-3 py-2 border-2 border-transparent focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-2.5 text-emerald-700 bg-white rounded-xl shadow-md hover:bg-emerald-50 transition active:scale-90"
          >
            <Camera className="w-5 h-5" />
          </button>
          <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={(e) => {
            const file = e.target.files?.[0];
            if(file) {
              const reader = new FileReader();
              reader.onload = () => setSelectedImage(reader.result as string);
              reader.readAsDataURL(file);
            }
          }} />
          <input 
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="बोलें या लिखें..." 
            className="flex-1 bg-transparent border-none outline-none text-sm font-medium placeholder-gray-400 px-2"
          />
          <button 
            onClick={toggleRecording}
            className={`p-2.5 rounded-xl transition-all shadow-md ${isRecording ? 'bg-red-600 text-white animate-pulse' : 'text-emerald-700 bg-white'}`}
          >
            <Mic className="w-5 h-5" />
          </button>
          {inputText && (
            <button onClick={handleSend} className="bg-emerald-700 text-white p-2.5 rounded-xl shadow-lg hover:bg-emerald-800 animate-fade-in">
              <Send className="w-5 h-5" />
            </button>
          )}
        </div>
      </footer>

      {/* Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 flex justify-around items-center h-16 shadow-[0_-4px_15px_rgba(0,0,0,0.05)] z-40">
        <button 
          onClick={() => setActiveTab('chat')}
          className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeTab === 'chat' ? 'text-emerald-700 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'chat' ? 'bg-emerald-50 rounded-xl p-2' : ''}`}>
             <MessageSquare className="w-5 h-5" />
          </div>
          <span className="text-[9px] font-black uppercase tracking-widest">चैट/जांच</span>
        </button>
        <button 
          onClick={() => setActiveTab('mandi')}
          className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeTab === 'mandi' ? 'text-emerald-700 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'mandi' ? 'bg-emerald-50 rounded-xl p-2' : ''}`}>
            <TrendingUp className="w-5 h-5" />
          </div>
          <span className="text-[9px] font-black uppercase tracking-widest">मंडी/मौसम</span>
        </button>
        <button 
          onClick={() => setActiveTab('technique')}
          className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeTab === 'technique' ? 'text-emerald-700 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'technique' ? 'bg-emerald-50 rounded-xl p-2' : ''}`}>
            <Leaf className="w-5 h-5" />
          </div>
          <span className="text-[9px] font-black uppercase tracking-widest">तकनीक</span>
        </button>
      </nav>

      {/* City Selection Modal */}
      {isCityModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end animate-fade-in">
          <div className="bg-white w-full max-w-md mx-auto rounded-t-3xl p-6 animate-slide-up">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-gray-800">अपना शहर चुनें</h3>
              <button onClick={() => setIsCityModalOpen(false)} className="p-2 bg-gray-100 rounded-full"><X className="w-5 h-5" /></button>
            </div>
            <div className="grid grid-cols-2 gap-3 max-h-80 overflow-y-auto no-scrollbar">
              {POPULAR_CITIES.map(c => (
                <button 
                  key={c}
                  onClick={() => { setCity(c); setIsCityModalOpen(false); }}
                  className={`p-4 rounded-2xl text-sm font-bold border transition ${city === c ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-gray-50 border-gray-200 text-gray-700 hover:bg-gray-100'}`}
                >
                  {c}
                </button>
              ))}
              <button 
                onClick={() => {
                  const custom = prompt("शहर का नाम लिखें:");
                  if(custom) setCity(custom);
                  setIsCityModalOpen(false);
                }}
                className="p-4 rounded-2xl text-sm font-bold border-2 border-dashed border-emerald-300 text-emerald-600 hover:bg-emerald-50"
              >
                + अन्य शहर
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Language Selection Modal */}
      {isLangModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-white w-full rounded-3xl p-6 shadow-2xl animate-pop-in">
            <h3 className="text-xl font-black text-gray-800 mb-6 text-center">भाषा चुनें (Language)</h3>
            <div className="grid grid-cols-1 gap-3">
              {LANGUAGES.map(lang => (
                <button 
                  key={lang.code}
                  onClick={() => { setSelectedLang(lang); setIsLangModalOpen(false); }}
                  className={`flex items-center justify-between p-4 rounded-2xl text-base font-bold border-2 transition ${selectedLang.code === lang.code ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-white border-gray-100 text-gray-600 hover:border-emerald-200'}`}
                >
                  {lang.label}
                  {selectedLang.code === lang.code && <div className="w-3 h-3 bg-emerald-600 rounded-full"></div>}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.3s ease-out; }
        .animate-slide-up { animation: slideUp 0.4s cubic-bezier(0.16, 1, 0.3, 1); }
        .animate-pop-in { animation: popIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { transform: translateY(100%); } to { transform: translateY(0); } }
        @keyframes popIn { from { transform: scale(0.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
      `}</style>
    </div>
  );
};

const RefreshCw = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg>
);

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  AlertCircle, 
  Loader2,
  X,
  Mic,
  Volume2,
  ChevronRight,
  TrendingUp,
  BookOpen,
  MessageSquare,
  ChevronDown,
  CloudSun,
  Globe,
  Settings,
  Droplets,
  Sprout,
  RefreshCw
} from 'lucide-react';
import { analyzeCrop } from './services/geminiService';
import { Message, MandiData, WeatherData } from './types';

const LANGUAGES = [
  { code: 'hi', label: 'हिन्दी' },
  { code: 'mr', label: 'मराठी' },
  { code: 'pa', label: 'ਪੰਜਾਬੀ' },
  { code: 'en', label: 'English' }
];

const POPULAR_CITIES = [
  "लखनऊ", "पटना", "इंदौर", "वाराणसी", 
  "नागपुर", "जयपुर", "भोपाल"
];

type Tab = 'chat' | 'mandi' | 'technique';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('chat');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: "नमस्ते किसान भाई! मैं किसान-चक्षु AI हूँ। अपनी फसल की फोटो भेजें या बोलकर सवाल पूछें।",
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isCityModalOpen, setIsCityModalOpen] = useState(false);
  const [isLangModalOpen, setIsLangModalOpen] = useState(false);
  const [city, setCity] = useState("वाराणसी");
  const [tempCity, setTempCity] = useState("वाराणसी");
  const [citySearchQuery, setCitySearchQuery] = useState("");
  const [selectedLang, setSelectedLang] = useState(LANGUAGES[0]);

  // Dashboard Data
  const [mandiRates, setMandiRates] = useState<MandiData[]>([]);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [isDashboardLoading, setIsDashboardLoading] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.onresult = (e: any) => {
        setInputText(e.results[0][0].transcript);
        setIsRecording(false);
      };
      recognitionRef.current.onend = () => setIsRecording(false);
    }
  }, []);

  const fetchDashboardData = async () => {
    if (activeTab !== 'mandi') return;
    setIsDashboardLoading(true);
    try {
      const prompt = `${city} शहर के लिए आज के 3 प्रमुख फसलों के मंडी भाव और मौसम का डेटा JSON फॉर्मेट में दें।`;
      const { text } = await analyzeCrop(prompt, undefined, city, "English");

      setMandiRates([
        { crop: 'गेहूं (Wheat)', price: '₹2,450', trend: 'up' },
        { crop: 'टमाटर (Tomato)', price: '₹1,200', trend: 'down' },
        { crop: 'चावल (Rice)', price: '₹3,800', trend: 'stable' }
      ]);
      setWeather({ temp: '32°C', condition: 'धूप खिली है', humidity: '45%' });
    } catch (e) {
      console.error(e);
    } finally {
      setIsDashboardLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'mandi') fetchDashboardData();
  }, [activeTab, city]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = selectedLang.code === 'hi' ? 'hi-IN' : 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleSend = async () => {
    if (!inputText.trim() && !selectedImage) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    const query = inputText;
    const img = selectedImage;
    setInputText('');
    setSelectedImage(null);

    try {
      const { text, sources } = await analyzeCrop(query, img || undefined, city, selectedLang.label);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources,
        timestamp: new Date()
      }]);
    } catch (err) {
      setMessages(prev => [...prev, {
        id: 'err',
        role: 'assistant',
        content: "क्षमा करें, तकनीकी समस्या आई।",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
      setTimeout(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
      }, 100);
    }
  };

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      recognitionRef.current?.start();
      setIsRecording(true);
    }
  };

  const filteredCities = POPULAR_CITIES.filter(c => 
    c.includes(citySearchQuery)
  );

  return (
    <div className="flex flex-col h-screen max-w-md mx-auto bg-gray-50 font-['Hind'] shadow-2xl relative overflow-hidden">

      {/* Header */}
      <header className="bg-[#14532d] text-white pt-6 pb-4 px-4 shadow-lg z-30">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className="bg-green-100/10 p-1.5 rounded-lg border border-white/10">
              <Sprout className="w-5 h-5 text-green-300" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">किसान-चक्षु AI</h1>
          </div>
          <button 
            onClick={() => setIsLangModalOpen(true)}
            className="flex items-center bg-[#1a4a2e] rounded-md px-3 py-1.5 border border-green-800 text-xs font-bold hover:bg-green-800 transition shadow-inner"
          >
            <Globe className="w-3 h-3 mr-1.5" />
            <span>{selectedLang.label}</span>
            <ChevronDown className="w-3 h-3 ml-1" />
          </button>
        </div>

        {/* City Bar */}
        <div 
          onClick={() => {
            setTempCity(city);
            setIsCityModalOpen(true);
          }}
          className="bg-[#0f3d23] rounded-xl p-3 flex items-center justify-between cursor-pointer border border-green-800/30 hover:bg-[#124b2a] transition active:scale-95"
        >
          <div className="flex items-center gap-3">
            <div className="p-1.5 bg-green-500/20 rounded-full">
              <MapPin className="w-4 h-4 text-green-400" />
            </div>
            <span className="text-sm font-semibold">{city} का अपडेट</span>
          </div>
          <ChevronRight className="w-4 h-4 text-green-600" />
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-4 bg-white relative no-scrollbar" ref={scrollRef}>
        {activeTab === 'chat' && (
          <div className="space-y-6 pb-10">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start animate-fade-in'}`}>
                <div className={`max-w-[88%] relative ${msg.role === 'user' ? 'bg-emerald-700 text-white rounded-2xl rounded-tr-none' : 'bg-white border border-gray-100 shadow-md rounded-2xl rounded-tl-none'} p-4`}>
                  {msg.image && <img src={msg.image} className="rounded-xl mb-3 max-h-64 w-full object-cover shadow-sm" />}
                  <div className="text-[15px] leading-relaxed whitespace-pre-wrap">{msg.content}</div>

                  {msg.role === 'assistant' && (
                    <button 
                      onClick={() => speakText(msg.content)}
                      className="mt-4 flex items-center gap-2 text-emerald-700 text-xs font-black bg-emerald-50 px-4 py-2 rounded-full hover:bg-emerald-100 transition border border-emerald-100"
                    >
                      <Volume2 className="w-4 h-4" /> सुनें
                    </button>
                  )}
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex justify-start items-center gap-3 text-emerald-600 font-bold text-xs animate-pulse bg-emerald-50 w-fit p-3 rounded-xl border border-emerald-100">
                <Loader2 className="w-4 h-4 animate-spin" />
                खोज रहा हूँ...
              </div>
            )}
          </div>
        )}

        {activeTab === 'mandi' && (
          <div className="space-y-5 pt-2 pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-bold text-emerald-900">बाज़ार और मौसम</h2>
              <button onClick={fetchDashboardData} className="p-2 text-emerald-600 bg-emerald-50 rounded-full">
                <RefreshCw className={`w-4 h-4 ${isDashboardLoading ? 'animate-spin' : ''}`} />
              </button>
            </div>

            {weather && (
              <div className="bg-gradient-to-br from-blue-500 to-blue-700 p-5 rounded-2xl text-white shadow-lg border-b-4 border-blue-800">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-sm font-medium opacity-80">आज का तापमान</p>
                    <p className="text-4xl font-black">{weather.temp}</p>
                  </div>
                  <CloudSun className="w-12 h-12" />
                </div>
                <div className="mt-4 flex gap-4 text-xs font-bold">
                  <span className="flex items-center gap-1 bg-white/20 px-3 py-1.5 rounded-full"><Droplets className="w-3 h-3" /> {weather.humidity} उमस</span>
                  <span className="flex items-center gap-1 bg-white/20 px-3 py-1.5 rounded-full">{weather.condition}</span>
                </div>
              </div>
            )}

            <div className="space-y-3">
              <p className="text-xs font-black text-gray-400 uppercase tracking-widest">ताज़ा मंडी भाव</p>
              {mandiRates.map((item, i) => (
                <div key={i} className="flex items-center justify-between bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-amber-50 rounded-lg flex items-center justify-center text-amber-600 font-bold border border-amber-100">
                      {item.crop[0]}
                    </div>
                    <div>
                      <p className="font-bold text-sm text-gray-800">{item.crop}</p>
                      <p className="text-[10px] text-gray-400 font-medium">प्रति क्विंटल</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-emerald-700">{item.price}</p>
                    <span className={`text-[10px] font-bold ${item.trend === 'up' ? 'text-green-500' : item.trend === 'down' ? 'text-red-500' : 'text-gray-400'}`}>
                      {item.trend === 'up' ? '↑ लाभ' : item.trend === 'down' ? '↓ गिरावट' : '• स्थिर'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'technique' && (
          <div className="space-y-4 pt-2 pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-bold text-emerald-900">खेती की नई तकनीक</h2>
              <BookOpen className="text-emerald-300 w-6 h-6" />
            </div>
            {[
              { title: "वर्मीकम्पोस्ट (Kenchua Khad)", desc: "जैविक कचरे से बेहतरीन खाद बनाने की सरल विधि।", tag: "जैविक" },
              { title: "मल्चिंग तकनीक", desc: "मिट्टी में नमी बनाए रखें और खरपतवार रोकें।", tag: "पानी बचत" },
              { title: "ड्रोन से कीटनाशक छिड़काव", desc: "कम मेहनत में पूरे खेत की सुरक्षा।", tag: "आधुनिक" },
              { title: "सोलार वाटर पंप", desc: "बिजली के बिना सिंचाई का टिकाऊ तरीका।", tag: "सरकारी सहायता" }
            ].map((item, i) => (
              <div key={i} className="group bg-white p-4 rounded-2xl border border-gray-100 shadow-sm hover:border-emerald-500 hover:shadow-md transition cursor-pointer">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-[10px] font-bold bg-emerald-50 text-emerald-700 px-2 py-1 rounded border border-emerald-100">{item.tag}</span>
                  <ChevronRight className="w-4 h-4 text-gray-300" />
                </div>
                <h3 className="font-black text-sm text-gray-800 mb-1">{item.title}</h3>
                <p className="text-xs text-gray-500 leading-relaxed">{item.desc}</p>
              </div>
            ))}
          </div>
        )}
      </main>

      {/* Input Section */}
      <footer className="bg-white p-4 border-t border-gray-100 mb-16 shadow-[0_-10px_20px_rgba(0,0,0,0.02)]">
        {selectedImage && (
          <div className="mb-3 relative inline-block animate-bounce-in">
            <img src={selectedImage} className="w-20 h-20 rounded-2xl border-4 border-emerald-600 shadow-lg object-cover" />
            <button onClick={() => setSelectedImage(null)} className="absolute -top-3 -right-3 bg-red-600 text-white rounded-full p-1.5 shadow-lg border-2 border-white">
              <X className="w-3 h-3" />
            </button>
          </div>
        )}
        <div className="flex items-center gap-2 bg-gray-100 rounded-2xl px-3 py-2 border-2 border-transparent focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-2.5 text-emerald-700 bg-white rounded-xl shadow-md hover:bg-emerald-50 transition active:scale-90"
          >
            <Camera className="w-5 h-5" />
          </button>
          <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={(e) => {
            const file = e.target.files?.[0];
            if(file) {
              const reader = new FileReader();
              reader.onload = () => setSelectedImage(reader.result as string);
              reader.readAsDataURL(file);
            }
          }} />
          <input 
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="बोलें या लिखें..." 
            className="flex-1 bg-transparent border-none outline-none text-sm font-medium placeholder-gray-400 px-2"
          />
          <button 
            onClick={toggleRecording}
            className={`p-2.5 rounded-xl transition-all shadow-md ${isRecording ? 'bg-red-600 text-white animate-pulse' : 'text-emerald-700 bg-white'}`}
          >
            <Mic className="w-5 h-5" />
          </button>
          {inputText && (
            <button onClick={handleSend} className="bg-emerald-700 text-white p-2.5 rounded-xl shadow-lg hover:bg-emerald-800 animate-fade-in">
              <Send className="w-5 h-5" />
            </button>
          )}
        </div>
