import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  Loader2,
  X,
  Mic,
  Volume2,
  ChevronRight,
  TrendingUp,
  BookOpen,
  MessageSquare,
  ChevronDown,
  CloudSun,
  Droplets,
  Sprout,
  RefreshCw,
  Navigation,
  Thermometer,
  CloudRain,
  Globe,
  Settings,
  LogOut,
  Moon,
  Sun,
  Mail,
  User,
  ShieldCheck,
  Bell,
  ArrowLeft,
  FileText,
  Lock,
  ChevronLeft
} from 'lucide-react';
import { analyzeCrop, getDashboardData } from './services/geminiService';
import { Message, MandiData, WeatherData, GroundingSource } from './types';

const LANGUAGES = [
  { code: 'hi', label: 'हिन्दी' },
  { code: 'mr', label: 'मराठी' },
  { code: 'pa', label: 'ਪੰਜਾਬੀ' },
  { code: 'en', label: 'English' }
];

const POPULAR_CITIES = [
  "लखनऊ", "पटना", "इंदौर", "वाराणसी", 
  "नागपुर", "जयपुर", "भोपाल", "पुणे", "अमृतसर", "नाशिक"
];

type Tab = 'chat' | 'mandi' | 'technique' | 'settings';
type SettingsView = 'main' | 'terms' | 'privacy' | 'notifications';

const App: React.FC = () => {
  // Auth State
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('isLoggedIn') === 'true');
  const [user, setUser] = useState<{name: string, email: string} | null>(() => {
    const saved = localStorage.getItem('user');
    return saved ? JSON.parse(saved) : null;
  });
  const [authEmail, setAuthEmail] = useState('');
  const [authName, setAuthName] = useState('');
  const [authStep, setAuthStep] = useState<'initial' | 'email-details'>('initial');
  const [authLoading, setAuthLoading] = useState(false);

  // Theme State
  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');

  // Navigation Sub-states
  const [settingsView, setSettingsView] = useState<SettingsView>('main');

  // App State
  const [activeTab, setActiveTab] = useState<Tab>('chat');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: "नमस्ते किसान भाई! मैं आपका किसान मित्र हूँ। अपनी फसल की फोटो भेजें या बोलकर सवाल पूछें।",
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isCityModalOpen, setIsCityModalOpen] = useState(false);
  const [isLangModalOpen, setIsLangModalOpen] = useState(false);
  const [pushEnabled, setPushEnabled] = useState(true);

  // City State Management
  const [city, setCity] = useState("वाराणसी");
  const [tempCity, setTempCity] = useState("वाराणसी");
  const [citySearchQuery, setCitySearchQuery] = useState("");

  // UI Settings
  const [selectedLang, setSelectedLang] = useState(LANGUAGES[0]);

  // Dashboard Data
  const [mandiRates, setMandiRates] = useState<MandiData[]>([]);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [dashboardSources, setDashboardSources] = useState<GroundingSource[]>([]);
  const [isDashboardLoading, setIsDashboardLoading] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Persist Theme
  useEffect(() => {
    localStorage.setItem('theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  // Persist Auth
  useEffect(() => {
    localStorage.setItem('isLoggedIn', isLoggedIn.toString());
    if (user) localStorage.setItem('user', JSON.stringify(user));
    else localStorage.removeItem('user');
  }, [isLoggedIn, user]);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current && activeTab === 'chat') {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  // Handle Voice Recognition
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.onresult = (e: any) => {
        const transcript = e.results[0][0].transcript;
        setInputText(transcript);
        setIsRecording(false);
      };
      recognitionRef.current.onend = () => setIsRecording(false);
      recognitionRef.current.onerror = () => setIsRecording(false);
    }
  }, []);

  const fetchDashboardData = async () => {
    setIsDashboardLoading(true);
    try {
      const result = await getDashboardData(city);
      if (result && result.mandi && result.weather) {
        setMandiRates(result.mandi);
        setWeather(result.weather);
        setDashboardSources(result.sources || []);
      } else {
        setMandiRates([
          { crop: 'गेहूं', price: '₹2,450', trend: 'up' },
          { crop: 'टमाटर', price: '₹1,200', trend: 'down' }
        ]);
        setWeather({ temp: '32°C', condition: 'धूप खिली है', humidity: '45%' });
        setDashboardSources([]);
      }
    } catch (e) {
      console.error("Dashboard fetch error:", e);
    } finally {
      setIsDashboardLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'mandi' && isLoggedIn) {
      fetchDashboardData();
    }
  }, [activeTab, city, isLoggedIn]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = selectedLang.code === 'hi' ? 'hi-IN' : 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleSend = async () => {
    if (!inputText.trim() && !selectedImage) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    const query = inputText;
    const img = selectedImage;
    setInputText('');
    setSelectedImage(null);

    try {
      const { text, sources } = await analyzeCrop(query, img || undefined, city, selectedLang.label);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources: sources,
        timestamp: new Date()
      }]);
    } catch (err) {
      setMessages(prev => [...prev, {
        id: 'err',
        role: 'assistant',
        content: "क्षमा करें, तकनीकी समस्या आई। कृपया पुनः प्रयास करें।",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsRecording(true);
      } catch (e) {
        alert("Speech recognition is not available in your browser.");
      }
    }
  };

  const handleLocationDetection = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        setCity("पुणे (detected)");
        setIsCityModalOpen(false);
      }, () => {
        alert("Location access denied.");
      });
    }
  };

  const handleLogin = (type: 'google' | 'email') => {
    if (type === 'google') {
      setAuthLoading(true);
      setTimeout(() => {
        setUser({ name: "राजेश कुमार", email: "rajesh.kumar@gmail.com" });
        setIsLoggedIn(true);
        setAuthLoading(false);
      }, 1200);
    } else {
      if (!authEmail.includes('@')) {
        alert('सही ईमेल दर्ज करें');
        return;
      }
      setAuthStep('email-details');
    }
  };

  const completeEmailLogin = () => {
    if (!authName) {
      alert('अपना नाम दर्ज करें');
      return;
    }
    setAuthLoading(true);
    setTimeout(() => {
      setUser({ name: authName, email: authEmail });
      setIsLoggedIn(true);
      setAuthLoading(false);
    }, 1000);
  };

  const handleLogout = () => {
    if (window.confirm('क्या आप लॉगआउट करना चाहते हैं?')) {
      setIsLoggedIn(false);
      setUser(null);
      setActiveTab('chat');
      setSettingsView('main');
      setAuthStep('initial');
      setAuthEmail('');
      setAuthName('');
    }
  };

  const filteredCities = POPULAR_CITIES.filter(c => 
    c.includes(citySearchQuery) || citySearchQuery === ""
  );

  const showCustomCity = citySearchQuery.trim().length > 0 && !POPULAR_CITIES.includes(citySearchQuery.trim());

  if (!isLoggedIn) {
    return (
      <div className={`flex flex-col h-screen max-w-md mx-auto font-['Hind'] transition-colors duration-300 ${theme === 'dark' ? 'bg-emerald-950 text-emerald-50' : 'bg-emerald-900 text-white'}`}>
        <div className="flex-1 flex flex-col items-center justify-center px-8 text-center py-10">
          <div className="bg-white/10 p-6 rounded-[40px] mb-8 border border-white/20 animate-pop-in">
            <Sprout className="w-16 h-16 text-green-300" />
          </div>
          <h1 className="text-4xl font-black mb-2 tracking-tight">किसान मित्र</h1>
          <p className="text-emerald-100/70 mb-12 text-lg leading-tight">भारत के हर किसान का भरोसेमंद डिजिटल सलाहकार</p>

          <div className="w-full space-y-4">
            {authStep === 'initial' ? (
              <>
                <button 
                  onClick={() => handleLogin('google')}
                  disabled={authLoading}
                  className="w-full bg-white text-emerald-900 py-4 rounded-3xl font-black shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-50"
                >
                  {authLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : (
                    <>
                      <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-6 h-6" alt="google" />
                      Google से जुड़ें
                    </>
                  )}
                </button>

                <div className="flex items-center gap-4 py-2">
                  <div className="flex-1 h-px bg-white/10"></div>
                  <span className="text-[10px] font-black text-emerald-100/40 uppercase tracking-widest">अथवा</span>
                  <div className="flex-1 h-px bg-white/10"></div>
                </div>

                <div className="space-y-4">
                  <div className="relative group">
                    <Mail className="absolute left-4 top-4.5 w-5 h-5 text-emerald-100/30 group-focus-within:text-emerald-300 transition-colors" />
                    <input 
                      type="email" 
                      value={authEmail}
                      onChange={(e) => setAuthEmail(e.target.value)}
                      placeholder="ईमेल पता दर्ज करें (Email)"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-white placeholder-emerald-100/30 outline-none focus:border-green-400 focus:bg-white/10 transition shadow-inner"
                    />
                  </div>
                  <button 
                    onClick={() => handleLogin('email')}
                    className="w-full bg-emerald-700/50 border border-white/20 text-white py-4 rounded-3xl font-black hover:bg-emerald-700 transition active:scale-95 shadow-lg"
                  >
                    ईमेल से आगे बढ़ें
                  </button>
                </div>
              </>
            ) : (
              <div className="space-y-6 animate-fade-in text-left">
                <button 
                  onClick={() => setAuthStep('initial')}
                  className="flex items-center gap-1 text-emerald-200 font-bold mb-4 hover:underline"
                >
                  <ArrowLeft className="w-4 h-4" /> वापस जाएँ
                </button>
                <div className="space-y-4">
                  <div>
                    <label className="text-xs font-black text-emerald-200/60 uppercase mb-2 block tracking-wider">आपका पूरा नाम</label>
                    <div className="relative">
                      <User className="absolute left-4 top-4.5 w-5 h-5 text-emerald-100/30" />
                      <input 
                        type="text" 
                        value={authName}
                        onChange={(e) => setAuthName(e.target.value)}
                        placeholder="जैसे: राजेश कुमार"
                        className="w-full bg-white/5 border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-white placeholder-emerald-100/30 outline-none focus:border-green-400 focus:bg-white/10 transition"
                      />
                    </div>
                  </div>
                  <button 
                    onClick={completeEmailLogin}
                    disabled={authLoading}
                    className="w-full bg-green-500 text-emerald-950 py-5 rounded-3xl font-black shadow-xl hover:bg-green-400 transition active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2"
                  >
                    {authLoading && <Loader2 className="w-5 h-5 animate-spin" />}
                    ऐप शुरू करें
                  </button>
                </div>
              </div>
            )}
          </div>

          <p className="mt-auto pt-8 text-xs text-emerald-100/50 max-w-[280px]">
            शुरू करके आप हमारी <span className="underline cursor-pointer">शर्तों</span> और <span className="underline cursor-pointer">गोपनीयता नीति</span> से सहमत होते हैं।
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-screen max-w-md mx-auto transition-colors duration-300 shadow-2xl relative overflow-hidden font-['Hind'] ${theme === 'dark' ? 'bg-gray-950 text-gray-100' : 'bg-gray-50 text-gray-900'}`}>

      {/* HEADER SECTION */}
      <header className={`${theme === 'dark' ? 'bg-emerald-900' : 'bg-[#14532d]'} text-white pt-6 pb-4 px-4 shadow-lg z-30 transition-all duration-300`}>
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className="bg-green-100/10 p-1.5 rounded-lg border border-white/10">
              <Sprout className="w-5 h-5 text-green-300" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">किसान मित्र</h1>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition active:scale-90"
              title="बदलें लाइट/डार्क मोड"
            >
              {theme === 'dark' ? <Sun className="w-5 h-5 text-amber-300" /> : <Moon className="w-5 h-5 text-emerald-200" />}
            </button>
            <button 
              onClick={() => setIsLangModalOpen(true)}
              className="flex items-center bg-[#1a4a2e] rounded-md px-3 py-1.5 border border-green-800 text-xs font-bold hover:bg-green-800 transition shadow-inner"
            >
              <Globe className="w-3 h-3 mr-1.5" />
              <span>{selectedLang.label}</span>
              <ChevronDown className="w-3 h-3 ml-1" />
            </button>
          </div>
        </div>

        {/* City Location Banner */}
        <div 
          onClick={() => {
            setTempCity(city);
            setCitySearchQuery("");
