                    <li>आपके द्वारा अपलोड की गई फसल की तस्वीरें</li>
                    <li>आपकी ईमेल और बुनियादी जानकारी</li>
                  </ul>
                  <p><strong>डेटा सुरक्षा:</strong> हम आपके डेटा को एन्क्रिप्टेड रूप में सुरक्षित रखते हैं और इसे किसी भी तीसरे पक्ष को बिना अनुमति के नहीं बेचते।</p>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      {/* FLOATING CHAT INPUT BAR (Only in Chat) */}
      {activeTab === 'chat' && (
        <footer className={`p-4 border-t mb-16 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-20 transition-colors ${theme === 'dark' ? 'bg-gray-900 border-gray-800' : 'bg-white border-gray-100'}`}>
          {selectedImage && (
            <div className="mb-4 relative inline-block animate-pop-in">
              <img src={selectedImage} className="w-24 h-24 rounded-[30px] border-4 border-emerald-600 shadow-xl object-cover" />
              <button 
                onClick={() => setSelectedImage(null)} 
                className="absolute -top-3 -right-3 bg-red-600 text-white rounded-full p-1.5 shadow-lg border-2 border-white hover:bg-red-700 transition"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          )}
          <div className={`flex items-center gap-3 rounded-[28px] px-4 py-2 border-2 transition-all shadow-inner ${
            theme === 'dark' ? 'bg-gray-800 border-transparent focus-within:border-emerald-600' : 'bg-gray-100 border-transparent focus-within:border-emerald-500 focus-within:bg-white'
          }`}>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className={`p-3 rounded-2xl shadow-md transition active:scale-90 ${theme === 'dark' ? 'bg-gray-700 text-emerald-400' : 'bg-white text-emerald-700 hover:bg-emerald-50'}`}
              title="कैमरा"
            >
              <Camera className="w-6 h-6" />
            </button>
            <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={(e) => {
              const file = e.target.files?.[0];
              if(file) {
                const reader = new FileReader();
                reader.onload = () => setSelectedImage(reader.result as string);
                reader.readAsDataURL(file);
              }
            }} />
            <input 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="बोलें या लिखें..." 
              className={`flex-1 bg-transparent border-none outline-none text-base font-bold placeholder-gray-400 px-1 ${theme === 'dark' ? 'text-gray-100' : 'text-gray-800'}`}
            />
            <button 
              onClick={toggleRecording}
              className={`p-3 rounded-2xl transition-all shadow-md ${isRecording ? 'bg-red-600 text-white animate-pulse' : (theme === 'dark' ? 'bg-gray-700 text-emerald-400' : 'bg-white text-emerald-700 hover:bg-emerald-50')}`}
              title="वॉयस टाइपिंग"
            >
              <Mic className="w-6 h-6" />
            </button>
            {(inputText || selectedImage) && (
              <button 
                onClick={handleSend} 
                className="bg-emerald-700 text-white p-3 rounded-2xl shadow-lg hover:bg-emerald-800 animate-fade-in active:scale-90"
              >
                <Send className="w-6 h-6" />
              </button>
            )}
          </div>
        </footer>
      )}

      {/* BOTTOM TAB NAVIGATION */}
      <nav className={`fixed bottom-0 left-0 right-0 max-w-md mx-auto border-t flex justify-around items-center h-16 shadow-[0_-4px_25px_rgba(0,0,0,0.08)] z-40 transition-colors ${
        theme === 'dark' ? 'bg-gray-900 border-gray-800' : 'bg-white border-gray-100'
      }`}>
        <button 
          onClick={() => setActiveTab('chat')}
          className={`flex flex-col items-center gap-1.5 flex-1 transition-all duration-300 ${activeTab === 'chat' ? 'text-emerald-500 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'chat' ? (theme === 'dark' ? 'bg-emerald-900/40' : 'bg-emerald-50') + ' rounded-2xl p-2 shadow-sm' : ''}`}>
             <MessageSquare className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black uppercase tracking-tighter">चैट</span>
        </button>
        <button 
          onClick={() => setActiveTab('mandi')}
          className={`flex flex-col items-center gap-1.5 flex-1 transition-all duration-300 ${activeTab === 'mandi' ? 'text-emerald-500 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'mandi' ? (theme === 'dark' ? 'bg-emerald-900/40' : 'bg-emerald-50') + ' rounded-2xl p-2 shadow-sm' : ''}`}>
            <TrendingUp className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black uppercase tracking-tighter">मंडी</span>
        </button>
        <button 
          onClick={() => setActiveTab('technique')}
          className={`flex flex-col items-center gap-1.5 flex-1 transition-all duration-300 ${activeTab === 'technique' ? 'text-emerald-500 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'technique' ? (theme === 'dark' ? 'bg-emerald-900/40' : 'bg-emerald-50') + ' rounded-2xl p-2 shadow-sm' : ''}`}>
            <Leaf className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black uppercase tracking-tighter">तकनीक</span>
        </button>
        <button 
          onClick={() => {
            setActiveTab('settings');
            setSettingsView('main');
          }}
          className={`flex flex-col items-center gap-1.5 flex-1 transition-all duration-300 ${activeTab === 'settings' ? 'text-emerald-500 scale-110' : 'text-gray-400'}`}
        >
          <div className={`${activeTab === 'settings' ? (theme === 'dark' ? 'bg-emerald-900/40' : 'bg-emerald-50') + ' rounded-2xl p-2 shadow-sm' : ''}`}>
            <Settings className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black uppercase tracking-tighter">प्रोफाइल</span>
        </button>
      </nav>

      {/* CITY SELECTION MODAL */}
      {isCityModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-[4px] z-50 flex items-center justify-center p-6 animate-fade-in">
          <div className={`w-full max-w-sm rounded-[50px] p-8 shadow-2xl relative animate-pop-in ${theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white'}`}>
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-2.5">
                <Search className="w-7 h-7 text-emerald-600" />
                <h3 className="text-2xl font-black dark:text-white">अपना शहर खोजें</h3>
              </div>
              <button 
                onClick={() => setIsCityModalOpen(false)} 
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition active:scale-90"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className={`rounded-[25px] flex items-center px-6 py-4.5 mb-8 border-2 transition-all shadow-inner ${
              theme === 'dark' ? 'bg-gray-800 border-gray-700 focus-within:border-emerald-600' : 'bg-gray-50 border-transparent focus-within:border-emerald-600 focus-within:bg-white'
            }`}>
              <Search className="w-5 h-5 text-gray-400 mr-3" />
              <input 
                type="text" 
                placeholder="शहर का नाम..."
                value={citySearchQuery}
                onChange={(e) => {
                  setCitySearchQuery(e.target.value);
                  setTempCity(e.target.value);
                }}
                autoFocus
                className="bg-transparent border-none outline-none text-base font-bold w-full"
              />
            </div>

            <div className="mb-8">
              <div className="flex items-center justify-between mb-4 px-1">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">लोकप्रिय शहर</p>
                 <button 
                  onClick={handleLocationDetection}
                  className="flex items-center gap-1 text-[10px] font-black text-emerald-600 uppercase hover:underline"
                 >
                   <Navigation className="w-3 h-3" /> मेरी जगह खोजें
                 </button>
              </div>
              <div className="flex flex-wrap gap-2.5 max-h-48 overflow-y-auto no-scrollbar p-1">
                {filteredCities.map(c => (
                  <button 
                    key={c}
                    onClick={() => {
                      setTempCity(c);
                      setCitySearchQuery(c);
                    }}
                    className={`px-6 py-3 rounded-full text-sm font-black transition-all ${
                      tempCity === c 
                        ? 'bg-emerald-700 text-white shadow-xl scale-105 ring-4 ring-emerald-100' 
                        : (theme === 'dark' ? 'bg-gray-800 text-gray-400 border border-gray-700' : 'bg-gray-50 text-gray-900 border border-gray-100') + ' hover:opacity-80 active:scale-95'
                    }`}
                  >
                    {c}
                  </button>
                ))}

                {showCustomCity && (
                  <button 
                    onClick={() => setTempCity(citySearchQuery)}
                    className={`px-6 py-3 rounded-full text-sm font-black transition-all ${
                      tempCity === citySearchQuery 
                        ? 'bg-emerald-700 text-white shadow-xl scale-105 ring-4 ring-emerald-100' 
                        : 'bg-emerald-50 text-emerald-700 border-2 border-dashed border-emerald-200'
                    }`}
                  >
                    "{citySearchQuery}" चुनें
                  </button>
                )}
              </div>
            </div>

            <button 
              onClick={() => {
                const finalCity = tempCity.trim();
                if (finalCity) {
                  setCity(finalCity);
                  setIsCityModalOpen(false);
                  setCitySearchQuery("");
                }
              }}
              className="w-full bg-[#15803d] hover:bg-[#166534] text-white py-5 rounded-[25px] text-lg font-black shadow-xl active:scale-95 transition-all mb-2 flex items-center justify-center gap-2"
            >
              शहर अपडेट करें
            </button>
          </div>
        </div>
      )}

      {/* LANGUAGE MODAL */}
      {isLangModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-6 animate-fade-in">
          <div className={`w-full max-w-sm rounded-[40px] p-8 shadow-2xl animate-pop-in ${theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white'}`}>
            <h3 className="text-xl font-black mb-8 text-center uppercase tracking-widest">भाषा चुनें (Language)</h3>
            <div className="grid grid-cols-1 gap-4">
              {LANGUAGES.map(lang => (
                <button 
                  key={lang.code}
                  onClick={() => { setSelectedLang(lang); setIsLangModalOpen(false); }}
                  className={`flex items-center justify-between p-5 rounded-3xl text-lg font-black border-4 transition-all ${
                    selectedLang.code === lang.code 
                    ? 'bg-emerald-50 dark:bg-emerald-900/30 border-emerald-600 text-emerald-800 dark:text-emerald-400 shadow-inner' 
                    : (theme === 'dark' ? 'bg-gray-800 border-gray-700 text-gray-500' : 'bg-white border-gray-100 text-gray-500') + ' hover:border-emerald-200'
                  }`}
                >
                  {lang.label}
                  {selectedLang.code === lang.code && <div className="w-4 h-4 bg-emerald-600 rounded-full shadow-sm"></div>}
                </button>
              ))}
            </div>
            <button 
              onClick={() => setIsLangModalOpen(false)}
              className="w-full mt-6 py-4 text-gray-400 font-black text-sm uppercase tracking-widest hover:text-gray-600"
            >
              बंद करें
            </button>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        .animate-pop-in { animation: popIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes popIn { from { transform: scale(0.85); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        @font-face {
          font-family: 'Hind';
          font-style: normal;
          font-weight: 400;
          src: url('https://fonts.gstatic.com/s/hind/v16/5qh6ler9p_NWhR6S.woff2') format('woff2');
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  Send, 
  Leaf, 
  MapPin, 
  Search, 
  Loader2,
  X,
  Mic,
  Volume2,
  ChevronRight,
  TrendingUp,
  BookOpen,
  MessageSquare,
  ChevronDown,
  CloudSun,
  Droplets,
  Sprout,
  RefreshCw,
  Navigation,
  Thermometer,
  CloudRain,
  Globe,
  Settings,
  LogOut,
  Moon,
  Sun,
  Mail,
  User,
  ShieldCheck,
  Bell,
  ArrowLeft,
  FileText,
  Lock,
  ChevronLeft
} from 'lucide-react';
import { analyzeCrop, getDashboardData } from './services/geminiService';
import { Message, MandiData, WeatherData, GroundingSource } from './types';

const LANGUAGES = [
  { code: 'hi', label: 'हिन्दी' },
  { code: 'mr', label: 'मराठी' },
  { code: 'pa', label: 'ਪੰਜਾਬੀ' },
  { code: 'en', label: 'English' }
];

const POPULAR_CITIES = [
  "लखनऊ", "पटना", "इंदौर", "वाराणसी", 
  "नागपुर", "जयपुर", "भोपाल", "पुणे", "अमृतसर", "नाशिक"
];

type Tab = 'chat' | 'mandi' | 'technique' | 'settings';
type SettingsView = 'main' | 'terms' | 'privacy' | 'notifications';

const App: React.FC = () => {
  // Auth State
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('isLoggedIn') === 'true');
  const [user, setUser] = useState<{name: string, email: string} | null>(() => {
    const saved = localStorage.getItem('user');
    return saved ? JSON.parse(saved) : null;
  });

  // Login Form States
  const [authEmail, setAuthEmail] = useState('');
  const [authName, setAuthName] = useState('');
  const [authStep, setAuthStep] = useState<'initial' | 'email-details'>('initial');
  const [authLoading, setAuthLoading] = useState(false);

  // Theme State
  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');

  // Navigation Sub-states
  const [settingsView, setSettingsView] = useState<SettingsView>('main');
  const [activeTab, setActiveTab] = useState<Tab>('chat');

  // App Functional States
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: "नमस्ते किसान भाई! मैं आपका किसान मित्र हूँ। अपनी फसल की फोटो भेजें या बोलकर सवाल पूछें।",
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isCityModalOpen, setIsCityModalOpen] = useState(false);
  const [isLangModalOpen, setIsLangModalOpen] = useState(false);
  const [pushEnabled, setPushEnabled] = useState(true);

  // City/Mandi States
  const [city, setCity] = useState("वाराणसी");
  const [tempCity, setTempCity] = useState("वाराणसी");
  const [citySearchQuery, setCitySearchQuery] = useState("");
  const [selectedLang, setSelectedLang] = useState(LANGUAGES[0]);
  const [mandiRates, setMandiRates] = useState<MandiData[]>([]);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [dashboardSources, setDashboardSources] = useState<GroundingSource[]>([]);
  const [isDashboardLoading, setIsDashboardLoading] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Sync state with storage
  useEffect(() => {
    localStorage.setItem('theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('isLoggedIn', isLoggedIn.toString());
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    } else {
      localStorage.removeItem('user');
    }
  }, [isLoggedIn, user]);

  // Handle Speech Recognition
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = selectedLang.code === 'hi' ? 'hi-IN' : 'en-US';
      recognitionRef.current.onresult = (e: any) => {
        const transcript = e.results[0][0].transcript;
        setInputText(transcript);
        setIsRecording(false);
      };
      recognitionRef.current.onend = () => setIsRecording(false);
      recognitionRef.current.onerror = () => setIsRecording(false);
    }
  }, [selectedLang]);

  // Dashboard Data fetcher
  const fetchDashboardData = async () => {
    if (!isLoggedIn) return;
    setIsDashboardLoading(true);
    try {
      const result = await getDashboardData(city);
      if (result && result.mandi && result.weather) {
        setMandiRates(result.mandi);
        setWeather(result.weather);
        setDashboardSources(result.sources || []);
      } else {
        // Mock data as fallback
        setMandiRates([
          { crop: 'गेहूं', price: '₹2,450', trend: 'up' },
          { crop: 'टमाटर', price: '₹1,200', trend: 'down' },
          { crop: 'चावल', price: '₹3,100', trend: 'stable' }
        ]);
        setWeather({ temp: '32°C', condition: 'धूप खिली है', humidity: '45%' });
        setDashboardSources([]);
      }
    } catch (e) {
      console.error("Dashboard error:", e);
    } finally {
      setIsDashboardLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'mandi') fetchDashboardData();
  }, [activeTab, city]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = selectedLang.code === 'hi' ? 'hi-IN' : 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleSend = async () => {
    if (!inputText.trim() && !selectedImage) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    const query = inputText;
    const img = selectedImage;
    setInputText('');
    setSelectedImage(null);

    try {
      const { text, sources } = await analyzeCrop(query, img || undefined, city, selectedLang.label);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: text,
        sources: sources,
        timestamp: new Date()
      }]);
    } catch (err) {
      setMessages(prev => [...prev, {
        id: 'error',
        role: 'assistant',
        content: "क्षमा करें, तकनीकी समस्या आई। कृपया पुनः प्रयास करें।",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsRecording(true);
      } catch (e) {
        alert("माफ़ करें, आपका ब्राउज़र वॉइस टाइपिंग को सपोर्ट नहीं करता।");
      }
    }
  };

  // Auth Handlers
  const handleGoogleLogin = () => {
    setAuthLoading(true);
    setTimeout(() => {
      setUser({ name: "राजेश कुमार", email: "rajesh.kumar@gmail.com" });
      setIsLoggedIn(true);
      setAuthLoading(false);
    }, 1500);
  };

  const handleEmailContinue = () => {
    if (!authEmail || !authEmail.includes('@')) {
      alert('कृपया सही ईमेल पता दर्ज करें।');
      return;
    }
    setAuthStep('email-details');
  };

  const completeEmailLogin = () => {
    if (!authName.trim()) {
      alert('कृपया अपना नाम दर्ज करें।');
      return;
    }
    setAuthLoading(true);
    setTimeout(() => {
      setUser({ name: authName, email: authEmail });
      setIsLoggedIn(true);
      setAuthLoading(false);
    }, 1200);
  };

  const handleLogout = () => {
    if (confirm('क्या आप लॉगआउट करना चाहते हैं?')) {
      setIsLoggedIn(false);
      setUser(null);
      setAuthStep('initial');
      setAuthEmail('');
      setAuthName('');
      setActiveTab('chat');
    }
  };

  const filteredCities = POPULAR_CITIES.filter(c => 
    c.includes(citySearchQuery) || citySearchQuery === ""
  );

  const showCustomCity = citySearchQuery.trim().length > 0 && !POPULAR_CITIES.includes(citySearchQuery.trim());

  // Login Screen
  if (!isLoggedIn) {
    return (
      <div className={`flex flex-col h-screen max-w-md mx-auto transition-colors duration-300 font-['Hind'] ${theme === 'dark' ? 'bg-emerald-950 text-white' : 'bg-emerald-900 text-white'}`}>
        <div className="flex-1 flex flex-col items-center justify-center px-8 text-center pb-12">
          <div className="bg-white/10 p-6 rounded-[40px] mb-8 border border-white/20 animate-pop-in">
            <Sprout className="w-16 h-16 text-green-300" />
          </div>
          <h1 className="text-4xl font-black mb-2 tracking-tight">किसान मित्र</h1>
          <p className="text-emerald-100/70 mb-12 text-lg">खेती की हर समस्या का समाधान</p>

          <div className="w-full space-y-4">
            {authStep === 'initial' ? (
              <>
                <button 
                  onClick={handleGoogleLogin}
                  disabled={authLoading}
                  className="w-full bg-white text-emerald-900 py-4.5 rounded-[24px] font-black shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-50"
                >
                  {authLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : (
                    <>
                      <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-6 h-6" alt="google" />
                      Google से जुड़ें
                    </>
                  )}
                </button>

